(()=>{
'use strict';
const CURRENT='WB 2026 S2';
const LIMITS=[10,50,100];
const state={boot:null,ready:false,historic:{},current:{},players:[],playerByKey:new Map(),editions:[],editionRows:new Map(),allRows:[],leaders:[],allSort:'kills',editionSort:'kills',allLimit:10,editionLimit:10,allPlayerSearch:'',allTeamSearch:'',editionPlayerSearch:'',selected:[CURRENT],equalizeDrops:false};
const compareDetails={promise:null,s1:null,s2:null};
const esc=v=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
const js=v=>String(v??'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/0/g,'O').replace(/[^a-z0-9]/gi,'').toUpperCase();
const num=v=>Number(v)||0;
const teamLogos={AFROGAMES:'afg.webp',ALPHA7:'A7 2.webp',CIVIS:'Civis.webp','CIVIS SPORTS':'Civis.webp','CPT VOX':'cpt vox.webp','FLUXO W7M':'Fluxo 2.webp','INFLUENCE RAGE':'Influence Rage.webp',INTZ:'Intz 1.webp','INTZ ESPORTS':'Intz 1.webp',LOOPS:'Loops 1.webp',LOS:'Los.webp','LOUD SNICKERS':'loud 2.webp','RISE GAMING':'Rise 1.webp','RUSH GAMING':'Rush.webp','SX TET':'sx tet.webp','TEAM SOLID':'Team Solid 2.webp'};
function injectCss(){if(document.getElementById('cff-hall-lite-css'))return;const s=document.createElement('style');s.id='cff-hall-lite-css';s.textContent='.hall-player-link{border:0;background:none;padding:0;font:inherit;font-weight:800;cursor:pointer;color:#fff}.hall-player-link.is-inactive{color:#7d8591;opacity:.78}.hall-player-link:hover{color:var(--accent);opacity:1}.hall-lite-loading td{padding:24px!important;color:#8d96a5;text-align:center}.hall-current-team{display:flex;align-items:center;justify-content:center;gap:7px}.hall-current-team img{width:22px;height:22px;object-fit:contain}.hall-inactive-label{color:#707784;font-size:.8em}.hall-active-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#36d98b;margin-right:6px;vertical-align:middle}.hall-compare-tools{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;gap:12px;margin:4px 0 12px;padding:10px 12px;border:1px solid rgba(0,200,255,.22);background:rgba(0,200,255,.055);border-radius:9px}.hall-equalize-label{display:flex;align-items:center;gap:9px;color:#fff;font-weight:900;font-size:.82rem;letter-spacing:.4px;cursor:pointer}.hall-equalize-label input{width:17px;height:17px;accent-color:var(--accent)}.hall-compare-tools small{color:var(--text-muted);font-size:.74rem;font-weight:700}.hall-compare-note{margin-top:10px;color:#8fb4d8;font-size:.76rem;font-weight:800;text-align:center}.hall-compare-loading{grid-column:1/-1;padding:18px;text-align:center;color:var(--text-muted);border:1px solid var(--border);border-radius:8px}@media(max-width:700px){.hall-current-team span{display:none}.hall-player-link{max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:inline-block;vertical-align:middle}.hall-compare-tools{align-items:flex-start;flex-direction:column}.hall-compare-tools small{line-height:1.35}}';document.head.appendChild(s)}
async function getJson(url){const r=await fetch(url,{cache:'default'});if(!r.ok)throw new Error('Falha ao carregar '+url);return r.json()}
function currentPlayersFromJson(json){const raw=json&&json.players&&typeof json.players==='object'?Object.values(json.players):[];const out={};raw.forEach(p=>{const name=String(p.name||p.jogador||'').trim();if(!name)return;const key=norm(name);out[key]={name,team:String(p.team||p.equipe||'').trim(),k:num(p.kills??p.abates),q:num(p.matches??p.quedas)};});return out}
function build(){const historic=state.historic||{},current=state.current||{},byKey=new Map(),editionSet=[];const seenEd=new Set();
 const addEdition=e=>{e=String(e||'').trim();if(e&&!seenEd.has(e)&&e!==CURRENT){seenEd.add(e);editionSet.push(e)}};
 Object.entries(historic).forEach(([name,eds])=>{const key=norm(name);const item=byKey.get(key)||{key,name,active:false,team:'',editions:{}};Object.entries(eds||{}).forEach(([ed,st])=>{addEdition(ed);item.editions[ed]={k:num((st&&st.k)??(st&&st.kills)??(st&&st.abates)),q:num((st&&st.q)??(st&&st.quedas)??(st&&st.matches))}});byKey.set(key,item)});
 Object.entries(current).forEach(([key,p])=>{const item=byKey.get(key)||{key,name:p.name,active:false,team:'',editions:{}};item.active=true;item.team=p.team;item.currentName=p.name;item.editions[CURRENT]={k:p.k,q:p.q};byKey.set(key,item)});
 state.editions=[...editionSet,CURRENT];state.playerByKey=byKey;state.players=[...byKey.values()].sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
 const pre=state.players.map(p=>{let k=0,q=0;Object.entries(p.editions).forEach(([ed,st])=>{if(ed!==CURRENT){k+=num(st.k);q+=num(st.q)}});return{p,k,q}}).filter(x=>x.k||x.q).sort((a,b)=>b.k-a.k||b.q-a.q||a.p.name.localeCompare(b.p.name,'pt-BR'));
 const oldPos=new Map(pre.map((x,i)=>[x.p.key,i+1]));
 state.allRows=state.players.map(p=>{let totalK=0,totalQ=0,preK=0;Object.entries(p.editions).forEach(([ed,st])=>{totalK+=num(st.k);totalQ+=num(st.q);if(ed!==CURRENT)preK+=num(st.k)});return{...p,totalK,totalQ,preK,oldPos:oldPos.get(p.key)||null,avg:totalQ?totalK/totalQ:0}}).filter(r=>r.totalK||r.totalQ);
 state.editionRows.clear();state.editions.forEach(ed=>{const rows=state.players.map(p=>{const st=p.editions[ed];return st?{...p,k:num(st.k),q:num(st.q),avg:num(st.q)?num(st.k)/num(st.q):0}:null}).filter(Boolean).filter(r=>r.k||r.q);state.editionRows.set(ed,rows)});
 state.leaders=state.editions.map(ed=>{const rows=[...(state.editionRows.get(ed)||[])].sort((a,b)=>b.k-a.k||b.avg-a.avg||a.name.localeCompare(b.name,'pt-BR'));return rows[0]?{edition:ed,...rows[0]}:null}).filter(Boolean);
}
function playerButton(row){const label=row.currentName||row.name;return `<button type="button" class="hall-player-link${row.active?'':' is-inactive'}" onclick="openCurrentSeasonPlayer('${js(label)}','${js(row.team||'')}')" title="${row.active?'Jogando a WB 2026 S2':'Não está jogando a WB 2026 S2'}">${row.active?'<span class="hall-active-dot"></span>':''}${esc(row.name)}</button>`}
function teamCell(row){if(!row.active||!row.team)return '<span class="hall-inactive-label">Inativo</span>';const logo=teamLogos[row.team]||'escudo.webp';return `<div class="hall-current-team"><img src="${esc(logo)}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='escudo.webp'"><span>${esc(row.team)}</span></div>`}
function sorted(rows,mode){return [...rows].sort((a,b)=>{if(mode==='team')return String(a.team||'ZZZ').localeCompare(String(b.team||'ZZZ'),'pt-BR')||num(b.totalK??b.k)-num(a.totalK??a.k);if(mode==='quedas')return num(b.totalQuedas??b.q)-num(a.totalQuedas??a.q);if(mode==='media')return num(b.avg)-num(a.avg)||num(b.totalK??b.k)-num(a.totalK??a.k);return num(b.totalK??b.k)-num(a.totalK??a.k)||num(b.totalQuedas??b.q)-num(a.totalQuedas??a.q)})}
function progress(prefix,limit,total){const info=document.getElementById(prefix+'-range-info'),more=document.getElementById('btn-'+prefix+'-more'),less=document.getElementById('btn-'+prefix+'-less');if(info)info.textContent=total?`Exibindo Top 1–${Math.min(limit,total)} de ${total}`:'Nenhum jogador encontrado';if(more){more.style.display=limit<Math.min(100,total)?'inline-block':'none';more.textContent=limit===10?'Ver do Top 10 ao 50':'Ver do Top 50 ao 100'}if(less)less.style.display=limit>10?'inline-block':'none'}
function movement(row,rank){if(state.allSort!=='kills')return'';if(!row.oldPos)return '<span style="color:#4caf50;font-size:.8em">NOVO</span>';const d=row.oldPos-rank;return d>0?`<span style="color:#4caf50;font-size:.8em">▲${d}</span>`:d<0?`<span style="color:#f44336;font-size:.8em">▼${Math.abs(d)}</span>`:'<span style="color:#888;font-size:.8em">-</span>'}
function renderAll(){const body=document.querySelector('#table-history tbody');if(!body)return;const p=norm(state.allPlayerSearch),t=norm(state.allTeamSearch);let rows=state.allRows.filter(r=>(!p||norm(r.name).includes(p)||norm(r.currentName).includes(p))&&(!t||norm(r.team).includes(t)));rows=sorted(rows,state.allSort);progress('hist-all',state.allLimit,rows.length);body.innerHTML=rows.slice(0,state.allLimit).map((r,i)=>`<tr><td><div style="font-weight:bold;color:var(--accent)">${i+1}º</div>${movement(r,i+1)}</td><td style="text-align:left">${playerButton(r)}</td><td>${teamCell(r)}</td><td style="color:#fff;font-weight:bold">${r.totalK}</td><td>${r.totalQ}</td><td style="color:var(--accent)">${r.avg.toFixed(2)}</td></tr>`).join('')||'<tr><td colspan="6" style="color:#aaa;padding:20px">Nenhum jogador encontrado.</td></tr>'}
function selectedRows(){const map=new Map;state.selected.forEach(ed=>(state.editionRows.get(ed)||[]).forEach(r=>{const row=map.get(r.key)||{...r,k:0,q:0,avg:0};row.k+=r.k;row.q+=r.q;row.avg=row.q?row.k/row.q:0;map.set(r.key,row)}));return[...map.values()]}
function renderEdition(){const body=document.querySelector('#table-edition-history tbody');if(!body)return;if(!state.selected.length){body.innerHTML='<tr><td colspan="6" style="color:#aaa;padding:20px">Selecione uma edição.</td></tr>';progress('hist-edition',state.editionLimit,0);return}const p=norm(state.editionPlayerSearch);let rows=selectedRows().filter(r=>!p||norm(r.name).includes(p)||norm(r.currentName).includes(p));rows=sorted(rows,state.editionSort);progress('hist-edition',state.editionLimit,rows.length);body.innerHTML=rows.slice(0,state.editionLimit).map((r,i)=>`<tr><td style="color:var(--accent);font-weight:bold">${i+1}º</td><td style="text-align:left">${playerButton(r)}</td><td>${teamCell(r)}</td><td style="color:#fff;font-weight:bold">${r.k}</td><td>${r.q}</td><td style="color:var(--accent)">${r.avg.toFixed(2)}</td></tr>`).join('')||'<tr><td colspan="6" style="color:#aaa;padding:20px">Nenhum jogador encontrado.</td></tr>'}
function renderFilters(){const root=document.getElementById('edition-filters');if(root)root.innerHTML=state.editions.map(ed=>`<button type="button" class="day-chip ${state.selected.includes(ed)?'active':''}" onclick="toggleEdition('${js(ed)}')">${esc(ed)}</button>`).join('')}
function renderLeaders(){const body=document.querySelector('#table-hall-edition-leaders tbody');if(!body)return;body.innerHTML=state.leaders.map(r=>`<tr><td style="text-align:left;font-weight:800">${esc(r.edition)}</td><td style="text-align:left">${playerButton(r)}</td><td style="font-weight:900;color:var(--accent)">${r.k}</td><td>${r.q}</td><td>${r.avg.toFixed(2)}</td></tr>`).join('')}
function populateSummaryList(){const list=document.getElementById('hall-player-summary-list');if(list)list.innerHTML=state.players.map(p=>`<option value="${esc(p.name)}"></option>`).join('')}
function findPlayer(query){const n=norm(query);return state.playerByKey.get(n)||state.players.find(p=>norm(p.name).includes(n)||norm(p.currentName).includes(n))||null}
function summaryRows(p){return state.editions.map(ed=>{const st=p.editions[ed];return st?{ed,k:num(st.k),q:num(st.q),avg:num(st.q)?num(st.k)/num(st.q):0}:null}).filter(Boolean).filter(r=>r.k||r.q)}
async function renderSummary(ev){ev&&ev.preventDefault&&ev.preventDefault();await boot();const input=document.getElementById('hall-player-summary-input'),result=document.getElementById('hall-player-summary-result');if(!result)return;const p=findPlayer(input&&input.value);if(!p){result.className='hall-player-summary-empty';result.textContent='Jogador não encontrado no histórico de abates.';return}const rows=summaryRows(p),k=rows.reduce((s,r)=>s+r.k,0),q=rows.reduce((s,r)=>s+r.q,0);result.className='hall-player-summary-card';result.innerHTML=`<div class="hall-player-summary-head"><h3 class="hall-player-summary-name">${esc(p.name)}</h3>${p.active?'<span style="color:#36d98b;font-weight:900">ATIVO NA WB 2026 S2</span>':'<span style="color:#7d8591;font-weight:900">FORA DA WB ATUAL</span>'}</div><div class="hall-player-summary-mini"><span><strong>${k}</strong><small>Abates</small></span><span><strong>${q}</strong><small>Quedas</small></span><span><strong>${q?(k/q).toFixed(2):'0.00'}</strong><small>Média geral</small></span></div><div class="table-container" style="border:0;border-radius:0;margin:0"><table id="table-hall-player-summary"><thead><tr><th style="text-align:left">Torneio</th><th>K</th><th>Q</th><th>Média</th></tr></thead><tbody>${rows.map(r=>`<tr><td style="text-align:left">${esc(r.ed)}</td><td>${r.k}</td><td>${r.q}</td><td>${r.avg.toFixed(2)}</td></tr>`).join('')}</tbody></table></div>`}
function comparePlayers(){return state.players.filter(p=>summaryRows(p).length)}
function populateCompare(){const a=document.getElementById('hist-comp-p1'),b=document.getElementById('hist-comp-p2');if(!a||!b)return;const list=comparePlayers(),html=list.map(p=>`<option value="${esc(p.key)}">${esc(p.name)}</option>`).join('');a.innerHTML=html;b.innerHTML=html;if(b.options.length>1)b.selectedIndex=1;updateEditionOptions('hist-comp-p1','hist-comp-ed1');updateEditionOptions('hist-comp-p2','hist-comp-ed2');renderCompare()}
function updateEditions(playerId,editionId){const p=state.playerByKey.get(document.getElementById(playerId)?.value),select=document.getElementById(editionId);if(!p||!select)return;const old=select.value,eds=summaryRows(p).map(r=>r.ed);select.innerHTML=eds.map(ed=>`<option value="${esc(ed)}">${esc(ed)}</option>`).join('');if(eds.includes(old))select.value=old}
function isDetailedWbPair(e1,e2){return(e1==='WB 2026 S1'&&e2==='WB 2026 S2')||(e1==='WB 2026 S2'&&e2==='WB 2026 S1')}
function ensureEqualizeControl(show){let box=document.getElementById('hist-compare-equalize');const root=document.getElementById('hist-compare-result');if(!root)return null;if(!box){box=document.createElement('div');box.id='hist-compare-equalize';box.className='hall-compare-tools';box.innerHTML='<label class="hall-equalize-label"><input type="checkbox" id="hist-equalize-drops"> EQUIPARAR QUEDAS</label><small>Usa o mesmo número de quedas nas duas edições. Na S1, considera as primeiras quedas cronológicas do jogador.</small>';root.parentNode.insertBefore(box,root);box.querySelector('input').addEventListener('change',e=>{state.equalizeDrops=!!e.target.checked;renderCompare()})}box.hidden=!show;const input=box.querySelector('input');if(input)input.checked=!!state.equalizeDrops;return box}
function compareStageOrder(stage){const s=String(stage||'').toLowerCase();return s.includes('class')?0:s.includes('segunda')?1:s.includes('final')?2:3}
function indexDetailedRows(rows){const map=new Map;(rows||[]).forEach(r=>{const name=String(r.name||r.nome||'').trim();if(!name)return;const key=norm(name),item={name,team:String(r.team||r.equipe||''),stage:r.stage||'',day:num(r.day??r.dia),round:num(r.round??r.drop??r.queda),kills:num(r.kills??r.k),damage:num(r.damage??r.dano),assists:num(r.assists??r.assistencias),mvp:num(r.mvp)};if(!map.has(key))map.set(key,[]);map.get(key).push(item)});map.forEach(list=>list.sort((a,b)=>compareStageOrder(a.stage)-compareStageOrder(b.stage)||a.day-b.day||a.round-b.round));return map}
function rowsFromS1Json(json,stage){const out=[];if(Array.isArray(json?.entries)&&Array.isArray(json?.players)&&Array.isArray(json?.teams)){const stages=Array.isArray(json.stages)?json.stages:['classificatoria','final'],stageIndex=stages.indexOf(stage);json.entries.forEach(r=>{if(num(r?.[0])!==stageIndex)return;out.push({stage,day:num(r?.[1]),round:num(r?.[2]),name:json.players[r?.[4]]||'',team:json.teams[r?.[5]]||'',kills:num(r?.[6]),damage:num(r?.[7]),assists:num(r?.[8]),mvp:num(r?.[9])})});return out}const src=json&&json.dbJogadoresQuedas||{};Object.keys(src).sort((a,b)=>num(a)-num(b)).forEach(day=>{Object.keys(src[day]||{}).sort((a,b)=>num(a)-num(b)).forEach(round=>{(src[day][round]||[]).forEach(r=>out.push({stage,day:num(day),round:num(round),name:r.nome,team:r.equipe,kills:r.kills,damage:r.dano,assists:r.assists,mvp:r.mvp}))})});return out}
async function loadCompareDetails(){if(compareDetails.s1&&compareDetails.s2)return compareDetails;if(compareDetails.promise)return compareDetails.promise;compareDetails.promise=Promise.all([getJson('ffws-br-2026-s1/players.json?v=20260817-modular-s1-v1'),getJson('ffws-br-2026-s2/players.json')]).then(([s1,s2])=>{compareDetails.s1=indexDetailedRows([...rowsFromS1Json(s1,'classificatoria'),...rowsFromS1Json(s1,'final')]);compareDetails.s2=indexDetailedRows(Array.isArray(s2?.entries)?s2.entries:[]);return compareDetails}).finally(()=>{compareDetails.promise=null});return compareDetails.promise}
function detailedRowsFor(player,edition,details){const map=edition==='WB 2026 S1'?details.s1:edition==='WB 2026 S2'?details.s2:null;if(!map||!player)return[];const keys=[player.key,norm(player.name),norm(player.currentName)].filter(Boolean);for(const key of keys){const rows=map.get(key);if(rows&&rows.length)return rows}return[]}
function aggregateDetailed(rows,limit=0){const list=limit>0?rows.slice(0,limit):rows;return list.reduce((a,r)=>(a.k+=num(r.kills),a.q+=1,a.damage+=num(r.damage),a.assists+=num(r.assists),a.mvp+=num(r.mvp),a),{k:0,q:0,damage:0,assists:0,mvp:0})}
function formatInt(v){return Math.round(num(v)).toLocaleString('pt-BR')}
function renderClassicCompare(root,p1,p2,e1,e2,a,b){const av=a.q?a.k/a.q:0,bv=b.q?b.k/b.q:0;const metric=(label,x,y,fmt=v=>v)=>`<div class="stat-row"><div class="stat-val ${x>y?'winner':x<y?'loser':''}">${fmt(x)}</div><div class="stat-label">${label}</div><div class="stat-val ${y>x?'winner':y<x?'loser':''}">${fmt(y)}</div></div>`;root.innerHTML=`<div class="compare-box"><h2 style="color:#66b3ff;margin-bottom:5px">${esc(p1.name)}</h2><div style="color:var(--accent);font-weight:bold">${esc(e1)}</div></div><div class="compare-box"><h2 style="color:#ff6666;margin-bottom:5px">${esc(p2.name)}</h2><div style="color:var(--accent);font-weight:bold">${esc(e2)}</div></div><div class="hist-stats-full-width" style="grid-column:1/-1;background:var(--panel-bg);border-radius:8px;padding:15px;border:1px solid var(--border)">${metric('Abates (Kills)',a.k,b.k)}${metric('Quedas Jogadas',a.q,b.q)}${metric('Média K/D',av,bv,v=>v.toFixed(2))}</div>`}
async function renderCompare(){const p1=state.playerByKey.get(document.getElementById('hist-comp-p1')?.value),p2=state.playerByKey.get(document.getElementById('hist-comp-p2')?.value),e1=document.getElementById('hist-comp-ed1')?.value,e2=document.getElementById('hist-comp-ed2')?.value,root=document.getElementById('hist-compare-result');if(!p1||!p2||!e1||!e2||!root)return;const baseA=p1.editions[e1]||{k:0,q:0},baseB=p2.editions[e2]||{k:0,q:0},full=isDetailedWbPair(e1,e2);ensureEqualizeControl(full);if(!full)return renderClassicCompare(root,p1,p2,e1,e2,baseA,baseB);const seq=(renderCompare._seq||0)+1;renderCompare._seq=seq;root.innerHTML='<div class="hall-compare-loading">Carregando dados completos da WB 2026...</div>';try{const details=await loadCompareDetails();if(seq!==renderCompare._seq)return;const rowsA=detailedRowsFor(p1,e1,details),rowsB=detailedRowsFor(p2,e2,details);if(!rowsA.length||!rowsB.length){renderClassicCompare(root,p1,p2,e1,e2,baseA,baseB);root.insertAdjacentHTML('beforeend','<div class="hall-compare-note" style="grid-column:1/-1">Os dados detalhados não foram localizados para um dos jogadores; exibindo o comparador histórico padrão.</div>');return}let limit=0;if(state.equalizeDrops)limit=Math.min(rowsA.length,rowsB.length);const a=aggregateDetailed(rowsA,limit),b=aggregateDetailed(rowsB,limit),av=a.q?a.k/a.q:0,bv=b.q?b.k/b.q:0,ad=a.q?a.damage/a.q:0,bd=b.q?b.damage/b.q:0,aa=a.q?a.assists/a.q:0,ba=b.q?b.assists/b.q:0;const metric=(label,x,y,fmt=v=>v)=>`<div class="stat-row"><div class="stat-val ${x>y?'winner':x<y?'loser':''}">${fmt(x)}</div><div class="stat-label">${label}</div><div class="stat-val ${y>x?'winner':y<x?'loser':''}">${fmt(y)}</div></div>`;root.innerHTML=`<div class="compare-box"><h2 style="color:#66b3ff;margin-bottom:5px">${esc(p1.name)}</h2><div style="color:var(--accent);font-weight:bold">${esc(e1)}</div></div><div class="compare-box"><h2 style="color:#ff6666;margin-bottom:5px">${esc(p2.name)}</h2><div style="color:var(--accent);font-weight:bold">${esc(e2)}</div></div><div class="hist-stats-full-width" style="grid-column:1/-1;background:var(--panel-bg);border-radius:8px;padding:15px;border:1px solid var(--border)">${metric('Abates (Kills)',a.k,b.k,formatInt)}${metric('Quedas Jogadas',a.q,b.q,formatInt)}${metric('Média K/Q',av,bv,v=>v.toFixed(2))}${metric('Dano total',a.damage,b.damage,formatInt)}${metric('Dano / Queda',ad,bd,v=>formatInt(v))}${metric('Assistências',a.assists,b.assists,formatInt)}${metric('Assist. / Queda',aa,ba,v=>v.toFixed(2))}${metric('MVP da Queda',a.mvp,b.mvp,formatInt)}${state.equalizeDrops?`<div class="hall-compare-note">Equiparado em <strong>${limit} primeiras quedas</strong> de cada jogador.</div>`:`<div class="hall-compare-note">Dados completos disponíveis somente neste confronto entre WB 2026 S1 e WB 2026 S2.</div>`}</div>`}catch(err){console.error('[Hall compare detalhado]',err);renderClassicCompare(root,p1,p2,e1,e2,baseA,baseB)}}
function nextLimit(current,dir){const i=LIMITS.indexOf(current);return dir==='more'?LIMITS[Math.min(LIMITS.length-1,i+1)]:LIMITS[Math.max(0,i-1)]}
function loading(){['#table-history tbody','#table-edition-history tbody','#table-hall-edition-leaders tbody'].forEach(sel=>{const el=document.querySelector(sel);if(el)el.innerHTML='<tr class="hall-lite-loading"><td colspan="6">Carregando Hall da Fama...</td></tr>'})}
async function boot(){if(state.ready){renderAll();renderFilters();renderEdition();return state}if(state.boot)return state.boot;injectCss();loading();state.boot=Promise.all([getJson('lbffData.json'),getJson('ffws-br-2026-s2/player-stats.json')]).then(([historic,current])=>{state.historic=historic||{};state.current=currentPlayersFromJson(current);build();state.ready=true;renderAll();renderFilters();renderEdition();renderLeaders();populateSummaryList();populateCompare();return state}).catch(err=>{console.error('[Hall Lite]',err);document.querySelectorAll('.hall-lite-loading td').forEach(td=>td.textContent='Não foi possível carregar o Hall da Fama.');throw err}).finally(()=>{state.boot=null});return state.boot}
window.cffHallLiteBoot=boot;window.cffHallBoot=boot;
window.renderHistoricalRanking=renderAll;window.renderEditionRanking=renderEdition;window.buildEditionFilters=renderFilters;window.populateHistSelects=populateCompare;
window.setHallAllTimeSort=v=>{state.allSort=v||'kills';state.allLimit=10;renderAll()};
window.setHallEditionSort=v=>{state.editionSort=v||'kills';state.editionLimit=10;renderEdition()};
window.applyHallAllTimeSearch=()=>{state.allPlayerSearch=document.getElementById('hist-all-player-search')?.value||'';state.allTeamSearch=document.getElementById('hist-all-team-search')?.value||'';state.allLimit=10;renderAll()};
window.handleHallAllTimeSearchKey=e=>{if(e.key==='Enter'){e.preventDefault();window.applyHallAllTimeSearch()}};
window.setHallEditionPlayerSearch=v=>{state.editionPlayerSearch=v||'';state.editionLimit=10;renderEdition()};
window.changeHallAllTimeLimit=dir=>{state.allLimit=nextLimit(state.allLimit,dir);renderAll()};
window.changeHallEditionLimit=dir=>{state.editionLimit=nextLimit(state.editionLimit,dir);renderEdition()};
window.toggleEdition=ed=>{const i=state.selected.indexOf(ed);i>=0?state.selected.splice(i,1):state.selected.push(ed);renderFilters();renderEdition()};
window.cffHallRenderPlayerSummary=renderSummary;
window.updateEditionOptions=updateEditions;window.renderHistCompare=renderCompare;
})();
